define :rolling_clamp_value do |value, low, high|
  [[value.to_f, low].max, high].min
end

define :rolling_approach_value do |current, target, amount|
  current.to_f + ((target.to_f - current.to_f) * amount.to_f)
end

define :rolling_wait_until_playing do
  while (get(:playing) != true) or (get(:active_piece) != :rolling)
    sleep 0.5
  end
end

define :rolling_wait_music_beats do |beats|
  remaining=[beats.to_f, 0.0].max
  while remaining>0.0001
    if (get(:playing) == true) and (get(:active_piece) == :rolling)
      use_bpm get(:rolling_current_bpm).to_f
      step=[remaining, 1.0].min
      sleep step
      remaining=remaining-step
    else
      sleep 0.5
    end
  end
end

