live_loop :rolling_parameter_smoother do
  use_real_time
  set :rolling_current_bpm, rolling_approach_value(get(:rolling_current_bpm), get(:rolling_target_bpm), 0.22)
  set :rolling_master_amp, rolling_approach_value(get(:rolling_master_amp), get(:rolling_target_master_amp), 0.28)
  sleep 0.25
end

live_loop :rolling_music_beat_reporter do
  rolling_wait_until_playing
  use_bpm get(:rolling_current_bpm).to_f
  beat_count=get(:rolling_beat_count).to_i
  if beat_count<rolling_pickup_beats
    beat_number=beat_count+1
    bar_number=0
  else
    beat_number=((beat_count-rolling_pickup_beats)%4)+1
    bar_number=1+((beat_count-rolling_pickup_beats)/4)
  end
  strength=beat_number==1 ? 1.0 : 0.45
  osc "/music/beat", bar_number, beat_number, get(:rolling_current_bpm).to_f, strength
  if beat_number==1
    set :rolling_bar_count, bar_number
    osc "/music/bar", bar_number, "rolling_girl"
  end
  set :rolling_beat_count, (beat_count+1)%rolling_loop_beats
  rolling_wait_music_beats 1.0
end

live_loop :rolling_state_reporter do
  use_real_time
  rolling_report_state
  osc "/music/style", "rolling_girl", get(:rolling_current_style).to_s if get(:active_piece) == :rolling
  rolling_report_layers
  sleep 0.5
end

live_loop :rolling_rolling_girl_melody do
  rolling_perform_event_track rolling_melody_events, :melody, rolling_loop_beats
end

live_loop :rolling_rolling_girl_harmony do
  rolling_perform_event_track rolling_harmony_events, :harmony, rolling_loop_beats
end

live_loop :rolling_rolling_girl_bass do
  rolling_perform_event_track rolling_bass_events, :bass, rolling_loop_beats
end

live_loop :rolling_rolling_girl_rhythm do
  rolling_perform_event_track rolling_rhythm_events, :rhythm, rolling_loop_beats
end
